-- publish_monitor_diagnostics(uuid)
CREATE OR REPLACE FUNCTION public.publish_monitor_diagnostics(a uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
